using System.Diagnostics;
using System.Globalization;
using W=System.Windows;
using C=System.Windows.Controls;
using M=System.Windows.Media;
namespace CombinedStudio;
internal static class FpsTests {
 internal static int Run(string folder){Directory.CreateDirectory(folder);var log=new List<string>();void Check(bool ok,string name){if(!ok)throw new Exception(name);log.Add("PASS "+name);}try{
  string header="Application,ProcessID,SwapChainAddress,TimeInSeconds,msBetweenPresents";long tick=1000;var frames=new FpsFrames(()=>tick);frames.Feed(header);
  string Row(string name,int pid,string chain,double time,double ms)=>name+","+pid+","+chain+","+time.ToString("0.000000",CultureInfo.InvariantCulture)+","+ms.ToString("0.000000",CultureInfo.InvariantCulture);
  for(int i=1;i<=120;i++)frames.Feed(Row("\"game, name.exe\"",42,"0xabc",i/120d,1000d/120));var reading=frames.Reading(42);Check(reading!=null&&Math.Abs(reading.Fps-120)<.01,"120 FPS and quoted application parsed from real CSV schema");Check(reading.Name=="game, name.exe"&&Math.Abs(reading.FrameMs-1000d/120)<.01,"quoted names and frame-time units preserved");Check(Math.Abs(reading.Low1-120)<.01,"constant frame rate has matching 1% low");
  for(int i=1;i<=60;i++)frames.Feed(Row("game.exe",42,"0xdef",i/60d,1000d/60));Check(frames.Reading(42).Swapchain=="0xabc","dominant swapchain selected without combining frame streams");for(int i=1;i<=30;i++)frames.Feed(Row("other.exe",99,"0xabc",i/30d,1000d/30));Check(Math.Abs(frames.Reading(99).Fps-30)<.01,"process IDs are isolated");
  Check(!frames.Feed("game.exe,42,0xabc,2,0")&&!frames.Feed("game.exe,42,0xabc,2,NaN")&&!frames.Feed("game.exe,42,0xabc,2,Infinity"),"zero and non-finite frame times rejected");tick+=2600;Check(frames.Reading(42)==null,"stale readings clear instead of displaying frozen FPS");frames.Clear();Check(frames.Reading(99)==null,"stop clears all previous readings");frames.Feed(header);for(int i=0;i<6000;i++)frames.Feed(Row("game.exe",42,"0xabc",i/1000d,1));Check(frames.Reading(42).Frames<=4096,"frame history is bounded");frames.Feed(Row("game.exe",42,"0xabc",0,10));frames.Feed(Row("game.exe",42,"0xabc",.01,10));Check(frames.Reading(42).Frames==2,"timestamp reset starts fresh history");
  var family=FpsApplications.Family(100,new[]{new FpsApplications.Entry(100,1,"chrome.exe"),new FpsApplications.Entry(101,100,"chrome.exe"),new FpsApplications.Entry(102,101,"chrome.exe"),new FpsApplications.Entry(999,1,"other.exe")});Check(family.SetEquals(new[]{100,101,102}),"browser renderer descendants are discovered without including unrelated apps");var browserFrames=new FpsFrames();browserFrames.Feed(header);for(int i=1;i<=60;i++){browserFrames.Feed(Row("chrome.exe",102,"gpu",i/60d,1000d/60));browserFrames.Feed(Row("other.exe",999,"other",i/60d,1));}Check(browserFrames.Reading(family)?.Pid==102,"foreground browser reads GPU-child frames without manual PID selection");Check(Math.Abs(browserFrames.Reading(family).Fps-60)<.01,"unrelated applications do not inflate a single app's FPS");
  var app=new W.Application{ShutdownMode=W.ShutdownMode.OnExplicitShutdown};var rectangle=new System.Windows.Shapes.Rectangle{Width=100,Height=100,Fill=M.Brushes.Gold,RenderTransform=new M.RotateTransform(0)};var window=new W.Window{Title="YAIOpc FPS validation animation",Width=360,Height=260,ShowInTaskbar=false,ShowActivated=false,Content=new C.Grid{Background=M.Brushes.Black,Children={rectangle}}};
  window.Loaded+=async(_,_)=>{using var capture=new FpsCapture();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(16)};int angle=0;timer.Tick+=(_,_)=>((M.RotateTransform)rectangle.RenderTransform).Angle=(angle++%360);timer.Start();try{
    await capture.Start(false);Check(capture.Running&&capture.WorkerId>0,"private capture helper connects through current-user pipe");int worker=capture.WorkerId;FpsReading live=null;for(int i=0;i<180&&live==null&&capture.Running;i++){await Task.Delay(100);live=capture.Frames.Reading(Environment.ProcessId);}Check(live!=null&&live.Fps>0&&double.IsFinite(live.Fps),"real ETW frames captured from animated native WPF window");log.Add("INFO live fixture "+live.Fps.ToString("0.0")+" FPS / "+live.FrameMs.ToString("0.00")+" ms");using(var overlay=new FpsOverlay()){IntPtr before=CrosshairOverlay.GetForegroundWindow();overlay.Show(live,new System.Windows.Interop.WindowInteropHelper(window).Handle,0);Check((CrosshairOverlay.GetWindowLong(overlay.Handle,-20)&0x08000020)==0x08000020,"overlay is click-through and cannot activate");Check(CrosshairOverlay.GetForegroundWindow()==before,"overlay does not steal foreground focus");var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(230,78,96,96,M.PixelFormats.Pbgra32);bitmap.Render(overlay.Window);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(folder,"fps-overlay.png")))encoder.Save(file);overlay.Show(null,new System.Windows.Interop.WindowInteropHelper(window).Handle,0,"Desktop");Check(overlay.Window.IsVisible,"overlay remains visible without a foreground-process reading");overlay.Hide();Check(!overlay.Window.IsVisible,"overlay can be hidden independently of capture");}
capture.Stop();Check(!capture.Running&&capture.Frames.Reading(Environment.ProcessId)==null,"stop clears capture state");for(int i=0;i<40;i++){try{using var p=Process.GetProcessById(worker);if(p.HasExited)break;}catch(ArgumentException){break;}await Task.Delay(100);}bool gone;try{using var p=Process.GetProcessById(worker);gone=p.HasExited;}catch(ArgumentException){gone=true;}Check(gone,"helper exits after stop instead of leaving capture running");
   }catch(Exception ex){Environment.ExitCode=1;log.Add("FAIL "+ex+" | "+capture.Status);}finally{timer.Stop();window.Close();app.Shutdown(Environment.ExitCode);}};
  app.Run(window);File.WriteAllLines(Path.Combine(folder,"fps-tests.txt"),log);return Environment.ExitCode;
 }catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(folder,"fps-tests.txt"),log);return 1;}}
}